mapper.select:
SELECT p.id, p.type, p.content, p.bgm_url, p.is_subscriber_only, p.hashtags, p.created_at, p.updated_at, m.id AS member_id, m.nickname, m.profile_image, img.image_url, (SELECT COUNT(*) FROM post_interaction pi WHERE pi.post_id = p.id AND pi.interaction_type = 'LIKE') AS like_count, (SELECT COUNT(*) FROM comment c WHERE c.post_id = p.id) AS comment_count FROM post_main p INNER JOIN member m ON p.member_id = m.id LEFT JOIN post_image img ON p.id = img.post_id
AND p.type = 1
AND p.id < #{lastPostId}
ORDER BY p.id DESC, img.sort_order ASC LIMIT #{limit}

SELECT p.id, p.type, p.content, p.bgm_url, p.is_subscriber_only, p.hashtags, p.created_at, p.updated_at, m.id AS member_id, m.nickname, m.profile_image, img.image_url, (SELECT COUNT(*) FROM post_interaction pi WHERE pi.post_id = p.id AND pi.interaction_type = 'LIKE') AS like_count, (SELECT COUNT(*) FROM comment c WHERE c.post_id = p.id) AS comment_count FROM ( SELECT * FROM post_main WHERE type = 1 AND CONCAT(hashtags, ' ') LIKE CONCAT('%#', #{hashtag}, ' %')
AND id < #{lastPostId}
ORDER BY id DESC LIMIT #{limit} ) p INNER JOIN member m ON p.member_id = m.id LEFT JOIN post_image img ON p.id = img.post_id ORDER BY p.id DESC, img.sort_order ASC

SELECT image_url FROM post_image
WHERE post_id = #{postId}
ORDER BY sort_order ASC
